g.grass.group.visible=false; const gu=g.grass.update.bind(g.grass); g.grass.update=(...a)=>{ gu(...a); g.grass.group.visible=false; };
// open flat tundra: no water within 16 m, nothing standing within 18 m
const T=W.place('tundra'); let land=null;
for(let r=0;r<=260;r+=8) for(let a=0;a<36;a++){ const x=T.x+Math.cos(a/36*6.2832)*r, z=T.z+Math.sin(a/36*6.2832)*r; if(!W.inBounds(x,z,40)||W.waterAt(x,z)) continue; let ok=true; for(let k=0;k<12&&ok;k++){ if(W.waterAt(x+Math.cos(k/12*6.2832)*16,z+Math.sin(k/12*6.2832)*16)) ok=false; } if(!ok||C.circlesNear(x,z,18).length) continue; const sc=W.slopeAt(x,z)*10+W.grass[W.cellIndex(x,z)]/255+r*0.002; if(!land||sc<land.sc) land={x,z,sc}; }
