const pier=W.place('pier'), d=pier.dock; const gx=d.x1-d.x0, gz=d.z1-d.z0, gl=Math.hypot(gx,gz);
window.__sea={x:d.x1,z:d.z1,ux:gx/gl,uz:gz/gl};
