  await __wait(3000);
  return sp+': '+(b.max.x-b.min.x).toFixed(2)+' x '+(b.max.y-b.min.y).toFixed(2)+' x '+(b.max.z-b.min.z).toFixed(2)+' m, '+(geo.attributes.position.count/3)+' triangles, seen from '+hd.toFixed(1)+' m, view '+fov.toFixed(1)+' degrees';
};
