(()=>{
const g=__rhf.game, W=g.world, C=g.colliders, wl=g.wildlife;
// after the update above, force every herd's detail: near, or far
const up=wl.update;
wl.update=function(...args){ up.apply(this,args); for(const h of wl.herdList) if(h.far&&h.n) h.mesh.geometry=window.__forceFar?h.far:h.near; };
// no small plants either: the camera spot below is checked against the
// ground and the trees, not against bushes and flowers, which can hide a
// small animal at its switch distance
const small=new Set(['bush','willow','fern','fireweed','lupine','devilsClub','blueberry','labradorTea','cottonGrass','horsetail','skunkCabbage','mushroom']);
g.scene.traverse((o)=>{ if(o.name&&o.name.endsWith('-lod')&&small.has(o.name.slice(0,-4))) o.visible=false; });
// wait for frames really drawn (under load none may come in a few seconds)
window.__frames=(n)=>new Promise(r=>{const f=()=>(--n<=0?r():requestAnimationFrame(f));requestAnimationFrame(f);});
const V=g.camera.position.constructor;
// a camera spot at distance D from (tx,tz) with a clear line of sight to a
// point at height ty, the sun as near behind it as such a spot allows
const camSpot=(tx,tz,ty,D)=>{ let best=null; const L=__sunSide;
  for(let k=0;k<48;k++){ const a=k/48*6.2832; const ux=Math.cos(a), uz=Math.sin(a); const x=tx+ux*D, z=tz+uz*D;
    if(!W.inBounds(x,z,10)) continue; const wat=W.waterAt(x,z); if(wat&&wat.depth>0.05) continue; if(C.circlesNear(x,z,1.6).length) continue;
    const eye=W.heightAt(x,z)+1.7; let clear=true;
    for(let i=1;i<40;i++){ const t=i/40; const px=x+(tx-x)*t, pz=z+(tz-z)*t; if(W.heightAt(px,pz)>eye+(ty-eye)*t-0.25||C.circlesNear(px,pz,0.8).length){clear=false;break;} }
    if(!clear) continue; const sc=-(ux*L.x+uz*L.z); if(!best||sc<best.sc) best={x,z,sc}; }
  return best; };
// one species at exactly its switch distance (scale 1), in the game's own
// view (64 degrees high, as on a phone on its side); returns where on the
// screen the animal's middle is, for the crops
window.__pop=async(sp,far,o={})=>{
  const h=wl.herds[sp]; if(!h.near.boundingBox) h.near.computeBoundingBox(); const b=h.near.boundingBox;
