  if(o.sea){ const S=__sea; cx=S.x; cz=S.z; tx=cx+S.ux*D; tz=cz+S.uz*D; y0=o.y??0; }
  else { const L=__land; tx=L.x; tz=L.z; y0=W.heightAt(L.x,L.z)+(o.air?3.5:0); const c=window.__camAt?.[sp]||camSpot(tx,tz,y0+cy,D); if(!c) return sp+': no clear spot'; (window.__camAt||(window.__camAt={}))[sp]=c; cx=c.x; cz=c.z; }
  window.__forceFar=far;
  g.player.place(cx,cz,Math.atan2(-(tx-cx),-(tz-cz))); await __wait(300); await __frames(2);
  const eye=g.player.pos.y+1.7;
  const yaw=Math.atan2(tx-cx,tz-cz)+(Math.PI/2+0.5);
