  const p=new V(tx,y0+cy,tz).project(g.camera); const sx=(p.x+1)/2*innerWidth, sy=(1-p.y)/2*innerHeight;
  return sp+' at '+D.toFixed(1)+' m, '+(far?'far':'near')+' ('+h.mesh.geometry.index.count/3+' triangles) screen '+sx.toFixed(0)+','+sy.toFixed(0)+' height '+(b.max.y-b.min.y).toFixed(2)+' m';
};
return 'pop ready';
})()
